1	import { useEffect, useState, type FormEvent } from 'react';
2	import { formatMoney } from '../../ui/money';
3	import { InvoiceLineItems } from './InvoiceLineItems';
4	import { ProjectTags } from './ProjectTags';
5	
6	// Opened from the projects list: a project's detail view lists ITS invoices, shows the derived
7	// total, and lets you add a new invoice for an amount. Invoices are scoped to the project via
8	// /api/projects/<id>/invoices. Money renders with exactly two decimals.
9	type Invoice = {
10	  id: number;
11	  projectId: number;
12	  amount: number;
13	  status: string;
14	  issuedDate: string;
15	  dueDate: string;
16	};
17	
18	type Task = {
19	  id: number;
20	  projectId: number;
21	  title: string;
22	  done: boolean;
23	};
24	
25	export function ProjectDetail({ projectId }: { projectId: number }) {
26	  const [invoices, setInvoices] = useState<Invoice[]>([]);
27	  const [tasks, setTasks] = useState<Task[]>([]);
28	  // Which tasks to show: all of them, just the open ones, or just the finished ones.
29	  const [taskFilter, setTaskFilter] = useState('');
30	  const [amount, setAmount] = useState('');
31	  const [amountError, setAmountError] = useState(false);
32	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
33	
34	  async function load() {
35	    const res = await fetch(`/api/projects/${projectId}/invoices`);
36	    if (res.ok) {
37	      setInvoices(await res.json());
38	    }
39	  }
40	
41	  async function loadTasks() {
42	    const query = taskFilter ? `?filter=${encodeURIComponent(taskFilter)}` : '';
43	    const res = await fetch(`/api/projects/${projectId}/tasks${query}`);
44	    if (res.ok) {
45	      setTasks(await res.json());
46	    }
47	  }
48	
49	  useEffect(() => {
50	    void load();
51	  }, [projectId]);
52	
53	  useEffect(() => {
54	    void loadTasks();
55	  }, [projectId, taskFilter]);
56	
57	  // Tick a task off (or back on): toggles OPEN <-> DONE and reloads the list.
58	  async function onToggleTask(taskId: number) {
59	    const res = await fetch(`/api/tasks/${taskId}/toggle`, { method: 'POST' });
60	    if (res.ok) {
61	      await loadTasks();
62	    }
63	  }
64	
65	  async function onSubmit(event: FormEvent) {
66	    event.preventDefault();
67	    // An invoice must be for a real amount: a positive number, never zero or negative.
68	    const value = Number(amount);
69	    if (!(value > 0)) {
70	      setAmountError(true);
71	      return;
72	    }
73	    setAmountError(false);
74	    const res = await fetch(`/api/projects/${projectId}/invoices`, {
75	      method: 'POST',
76	      headers: { 'Content-Type': 'application/json' },
77	      body: JSON.stringify({ amount: Number(amount) }),
78	    });
79	    if (res.ok) {
80	      setAmount('');
81	      await load();
82	    }
83	  }
84	
85	  // Sort this project's invoices by due date (earliest due first) via the by-due endpoint.
86	  async function onSortByDue() {
87	    const res = await fetch(`/api/projects/${projectId}/invoices/by-due`);
88	    if (res.ok) {
89	      setInvoices(await res.json());
90	    }
91	  }
92	
93	  async function onSend(invoiceId: number) {
94	    const res = await fetch(`/api/invoices/${invoiceId}/send`, { method: 'POST' });
95	    if (res.ok) {
96	      await load();
97	    }
98	  }
99	
100	  async function onPay(invoiceId: number) {
101	    const res = await fetch(`/api/invoices/${invoiceId}/pay`, { method: 'POST' });
102	    if (res.ok) {
103	      await load();
104	    }
105	  }
106	
107	  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);
108	
109	  return (
110	    <section data-testid="project-detail">
111	      <ProjectTags projectId={projectId} />
112	
113	      <h2>Tasks</h2>
114	
115	      <label>
116	        Show
117	        <select
118	          data-testid="task-filter"
119	          value={taskFilter}
120	          onChange={(e) => setTaskFilter(e.target.value)}
121	        >
122	          <option value="">All tasks</option>
123	          <option value="OPEN">Open</option>
124	          <option value="DONE">Done</option>
125	        </select>
126	      </label>
127	
128	      <table data-testid="project-tasks-table">
129	        <thead>
130	          <tr>
131	            <th>Task</th>
132	            <th>Status</th>
133	            <th></th>
134	          </tr>
135	        </thead>
136	        <tbody>
137	          {tasks.map((task) => (
138	            <tr key={task.id} data-testid={`task-row-${task.id}`}>
139	              <td data-testid="task-title">{task.title}</td>
140	              <td data-testid="task-status">{task.done ? 'DONE' : 'OPEN'}</td>
141	              <td>
142	                <button
143	                  data-testid={`task-toggle-${task.id}`}
144	                  type="button"
145	                  onClick={() => onToggleTask(task.id)}
146	                >
147	                  {task.done ? 'Reopen' : 'Tick off'}
148	                </button>
149	              </td>
150	            </tr>
151	          ))}
152	        </tbody>
153	      </table>
154	
155	      <h2>Invoices</h2>
156	
157	      {openInvoiceId !== null ? (
158	        <InvoiceLineItems
159	          invoiceId={openInvoiceId}
160	          onBack={() => {
161	            setOpenInvoiceId(null);
162	            void load();
163	          }}
164	        />
165	      ) : (
166	      <>
167	      <form data-testid="invoice-form" onSubmit={onSubmit}>
168	        <input
169	          data-testid="invoice-form-amount"
170	          placeholder="Amount"
171	          value={amount}
172	          onChange={(e) => setAmount(e.target.value)}
173	        />
174	        {amountError && (
175	          <p data-testid="invoice-form-amount-error">
176	            Enter an amount greater than zero.
177	          </p>
178	        )}
179	        <button data-testid="invoice-form-submit" type="submit">
180	          Add invoice
181	        </button>
182	      </form>
183	
184	      <button data-testid="invoice-sort-due" type="button" onClick={onSortByDue}>
185	        Sort by due date
186	      </button>
187	
188	      <table data-testid="project-invoices-table">
189	        <thead>
190	          <tr>
191	            <th>Amount</th>
192	            <th>Issued</th>
193	            <th>Due</th>
194	            <th>Status</th>
195	            <th></th>
196	          </tr>
197	        </thead>
198	        <tbody>
199	          {invoices.map((invoice) => (
200	            <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
201	              <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
202	              <td data-testid="invoice-issued">{invoice.issuedDate}</td>
203	              <td data-testid="invoice-due">{invoice.dueDate}</td>
204	              <td data-testid="invoice-status">{invoice.status}</td>
205	              <td>
206	                <button
207	                  data-testid={`invoice-open-${invoice.id}`}
208	                  type="button"
209	                  onClick={() => setOpenInvoiceId(invoice.id)}
210	                >
211	                  Open
212	                </button>
213	                {/* Lifecycle: a DRAFT can be sent; only a SENT invoice can be paid. */}
214	                {invoice.status === 'DRAFT' && (
215	                  <button
216	                    data-testid={`invoice-send-${invoice.id}`}
217	                    type="button"
218	                    onClick={() => onSend(invoice.id)}
219	                  >
220	                    Send
221	                  </button>
222	                )}
223	                {invoice.status === 'SENT' && (
224	                  <button
225	                    data-testid={`invoice-pay-${invoice.id}`}
226	                    type="button"
227	                    onClick={() => onPay(invoice.id)}
228	                  >
229	                    Mark paid
230	                  </button>
231	                )}
232	              </td>
233	            </tr>
234	          ))}
235	        </tbody>
236	        <tfoot>
237	          <tr>
238	            <td data-testid="project-invoices-total">{formatMoney(total)}</td>
239	          </tr>
240	        </tfoot>
241	      </table>
242	      </>
243	      )}
244	    </section>
245	  );
246	}
